<?php

/**
 * Minimal PSR-4 autoloader for the App\ namespace so this project runs with
 * zero external dependencies (no composer install required). If a real
 * vendor/autoload.php is ever generated by composer, it is preferred.
 */

$vendorAutoload = dirname(__DIR__, 2) . '/vendor/autoload.php';
if (is_file($vendorAutoload)) {
    require $vendorAutoload;
    return;
}

spl_autoload_register(function (string $class) {
    $prefix = 'App\\';
    if (!str_starts_with($class, $prefix)) {
        return;
    }
    $relative = substr($class, strlen($prefix));
    $path = dirname(__DIR__) . '/' . str_replace('\\', '/', $relative) . '.php';
    if (is_file($path)) {
        require $path;
    }
});
